const GENERATORS = Object.freeze([
  0x3b6a57b2n,
  0x26508e6dn,
  0x1ea119fan,
  0x3d4233ddn,
  0x2a1462b3n,
]);

export function polymod(values) {
  let checksum = 1n;

  for (const value of values) {
    const top = checksum >> 25n;
    checksum = ((checksum & 0x1ffffffn) << 5n) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >> BigInt(index)) & 1n) === 1n) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum;
}

