export function expandHrp(hrp) {
  const expanded = [];

  for (const character of hrp) {
    expanded.push(BigInt(character.codePointAt(0) >> 5));
  }

  expanded.push(0n);

  for (const character of hrp) {
    expanded.push(BigInt(character.codePointAt(0) & 31));
  }

  return expanded;
}

