import { expandHrp } from './hrp.mjs';
import { polymod } from './polymod.mjs';

const CHECKSUM_LENGTH = 6;

function normalizeValue(value) {
  if (typeof value === 'bigint') {
    return value;
  }

  if (typeof value === 'number' && Number.isSafeInteger(value)) {
    return BigInt(value);
  }

  throw new TypeError('Bech32 values must be integers');
}

function normalizeValues(values) {
  return values.map(normalizeValue);
}

export function createChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...normalizeValues(data)];
  const padding = Array.from({ length: CHECKSUM_LENGTH }, () => 0n);
  const remainder = polymod([...values, ...padding]) ^ 1n;
  const checksum = [];

  for (let index = 0; index < CHECKSUM_LENGTH; index += 1) {
    const shift = BigInt(5 * (CHECKSUM_LENGTH - 1 - index));
    checksum.push(Number((remainder >> shift) & 31n));
  }

  return checksum;
}

export function verifyChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...normalizeValues(data)];
  return polymod(values) === 1n;
}

